<!--
 * Agent 定义（只读查询页）
 *
 * @path apps/agent-web/src/views/definition/index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * Agent 定义（只读查询页）
 * <p>消费后端 AgentDefinitionController 契约（auto-generated by bash/gen-contract.py）：
 * 顶部按 agentCode 查询详情（getByCode），下方展示全量定义列表（list()），
 * 列表操作列「查看」通过 getById({ id }) 弹出详情抽屉（展示 systemPrompt/modelConfig/toolNames 等完整字段）。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';
import { Page } from '@ydsz/common-ui';
import { h, ref } from 'vue';
import { ElButton, ElDescriptions, ElDescriptionsItem, ElDrawer, ElMessage, ElInput } from 'element-plus';
import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { getByCode, getById, list } from '#/api/agentDefinition';
import type { AgentDefinitionVO } from '#/api/models';

defineOptions({ name: 'DefinitionManagement' });

/** 顶部按编码查询的输入与结果 */
const queryCode = ref('');
const queryDetail = ref<AgentDefinitionVO | null>(null);
/** 列表「查看」详情抽屉状态 */
const detailVisible = ref(false);
const detail = ref<AgentDefinitionVO | null>(null);

const gridOptions: VxeTableGridOptions<AgentDefinitionVO> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    { field: 'agentCode', title: 'Agent编码', width: 140 },
    { field: 'agentName', title: 'Agent名称', width: 160 },
    { field: 'agentType', title: '类型', width: 120 },
    { field: 'description', title: '描述', width: 200, showOverflow: true },
    { field: 'temperature', title: '温度', width: 80 },
    { field: 'maxTokens', title: 'MaxTokens', width: 110 },
    { field: 'createdAt', title: '创建时间', width: 160 },
    { field: 'updatedAt', title: '更新时间', width: 160 },
    {
      field: 'action', title: '操作', width: 100, fixed: 'right',
      slots: { default: ({ row }) => h('div', { class: 'flex gap-1' }, [
        h(ElButton, { size: 'small', link: true, type: 'primary', onClick: () => handleView(row) }, () => '查看'),
      ]) },
    },
  ],
  height: 'auto',
  proxyConfig: {
    ajax: {
      query: async () => {
        const items = await list();
        return { items: items ?? [], total: items?.length ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
  formConfig: { enabled: true, items: [
      { field: 'agentCode', title: 'Agent编码', itemRender: { name: 'Input', props: { placeholder: 'Agent编码' } } },
      { field: 'agentName', title: 'Agent名称', itemRender: { name: 'Input', props: { placeholder: 'Agent名称' } } },
  ] },
};
const [Grid] = useYDSZVxeGrid({ gridOptions });

/** 按 Agent 编码查询定义详情，结果展示在顶部描述区 */
async function handleQueryByCode() {
  const code = queryCode.value.trim();
  if (!code) { ElMessage.warning('请输入Agent编码'); return; }
  try {
    queryDetail.value = await getByCode({ code });
    ElMessage.success('查询成功');
  } catch {
    queryDetail.value = null;
  }
}

/** 打开定义详情抽屉（getById({ id })） */
async function handleView(row: AgentDefinitionVO) {
  try {
    detail.value = await getById({ id: row.id ?? '' });
    detailVisible.value = true;
  } catch { /* 详情查询失败，由拦截器统一提示 */ }
}
</script>
<template>
  <Page auto-content-height>
    <div class="mb-3 flex items-center gap-2">
      <ElInput v-model="queryCode" placeholder="按Agent编码查询" clearable class="w-64" />
      <ElButton type="primary" @click="handleQueryByCode">查询</ElButton>
    </div>
    <ElDescriptions v-if="queryDetail" :column="3" border class="mb-3">
      <ElDescriptionsItem label="Agent编码">{{ queryDetail.agentCode }}</ElDescriptionsItem>
      <ElDescriptionsItem label="Agent名称">{{ queryDetail.agentName }}</ElDescriptionsItem>
      <ElDescriptionsItem label="类型">{{ queryDetail.agentType }}</ElDescriptionsItem>
      <ElDescriptionsItem label="温度">{{ queryDetail.temperature }}</ElDescriptionsItem>
      <ElDescriptionsItem label="MaxTokens">{{ queryDetail.maxTokens }}</ElDescriptionsItem>
      <ElDescriptionsItem label="工具列表">{{ queryDetail.toolNames }}</ElDescriptionsItem>
      <ElDescriptionsItem label="描述" :span="3">{{ queryDetail.description }}</ElDescriptionsItem>
      <ElDescriptionsItem label="系统提示词" :span="3">
        <pre class="whitespace-pre-wrap break-all">{{ queryDetail.systemPrompt }}</pre>
      </ElDescriptionsItem>
    </ElDescriptions>
    <Grid table-title="Agent定义列表" />
    <ElDrawer v-model="detailVisible" title="Agent定义详情" size="480px">
      <ElDescriptions v-if="detail" :column="1" border>
        <ElDescriptionsItem label="Agent编码">{{ detail.agentCode }}</ElDescriptionsItem>
        <ElDescriptionsItem label="Agent名称">{{ detail.agentName }}</ElDescriptionsItem>
        <ElDescriptionsItem label="类型">{{ detail.agentType }}</ElDescriptionsItem>
        <ElDescriptionsItem label="描述">{{ detail.description }}</ElDescriptionsItem>
        <ElDescriptionsItem label="系统提示词">
          <pre class="whitespace-pre-wrap break-all">{{ detail.systemPrompt }}</pre>
        </ElDescriptionsItem>
        <ElDescriptionsItem label="模型配置">
          <pre class="whitespace-pre-wrap break-all">{{ detail.modelConfig }}</pre>
        </ElDescriptionsItem>
        <ElDescriptionsItem label="工具列表">{{ detail.toolNames }}</ElDescriptionsItem>
        <ElDescriptionsItem label="温度">{{ detail.temperature }}</ElDescriptionsItem>
        <ElDescriptionsItem label="MaxTokens">{{ detail.maxTokens }}</ElDescriptionsItem>
        <ElDescriptionsItem label="创建人">{{ detail.createdBy }}</ElDescriptionsItem>
        <ElDescriptionsItem label="创建时间">{{ detail.createdAt }}</ElDescriptionsItem>
        <ElDescriptionsItem label="更新人">{{ detail.updatedBy }}</ElDescriptionsItem>
        <ElDescriptionsItem label="更新时间">{{ detail.updatedAt }}</ElDescriptionsItem>
      </ElDescriptions>
    </ElDrawer>
  </Page>
</template>